(() => {
  const API='api/tasks', KEY='day-reset-focus-v1', THEME_KEY='day-reset-theme-v1';
  const app=document.getElementById('app'), status=document.getElementById('sync-status');
  const $=id=>document.getElementById(id); let tasks=[], view='today', focusId=null, busy=false, editingId=null, loadError=false, hasLoaded=false, refreshGeneration=0;
  let createDraft={title:'',group:'',estimate:''}, createDraftFocus=null, createDraftResetPending=false, createError='', draggedTaskId=null;
  const TIMER_CONFIG_KEY='day-reset-pomodoro-config-v1', TIMER_STATE_KEY='day-reset-pomodoro-state-v1', Timer=window.PomodoroTimer;
  const TIMER_RING_CIRCUMFERENCE=2*Math.PI*92;
  let timerConfig={...Timer.DEFAULT_CONFIG}, timerState=Timer.createState();
  try{const raw=localStorage.getItem(TIMER_CONFIG_KEY);if(raw){const parsed=Timer.validateConfig(JSON.parse(raw));if(parsed.valid)timerConfig=parsed.config;}}catch(_){}
  try{const raw=localStorage.getItem(TIMER_STATE_KEY);if(raw){const parsed=JSON.parse(raw);timerState=Timer.recover(parsed,Date.now());if(JSON.stringify(parsed)!==JSON.stringify(timerState))saveTimerState();}}catch(_){}
  function saveTimerConfig(){try{localStorage.setItem(TIMER_CONFIG_KEY,JSON.stringify(timerConfig));}catch(_){}}
  function saveTimerState(){try{localStorage.setItem(TIMER_STATE_KEY,JSON.stringify(timerState));}catch(_){}}
  function commitTimer(next){timerState=next;saveTimerState();updateTimerDisplay();}
  function timerRemaining(){return Timer.remainingMs(timerState,Date.now())??({work:timerConfig.workMinutes,short:timerConfig.shortBreakMinutes,long:timerConfig.longBreakMinutes}[timerState.phase]*60000);}
  function updateTimerDisplay(){
    if(timerState.status==='running'){const recovered=Timer.recover(timerState,Date.now());if(recovered.status==='finished'){timerState=recovered;saveTimerState();}}
    const display=$('timer-remaining');if(!display)return;
    const ms=timerRemaining(),seconds=Math.ceil(ms/1000);
    display.textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;
    const label=$('timer-state');if(label)label.textContent=timerState.status==='running'?'Running':timerState.status==='paused'?'Paused':timerState.status==='finished'?'Complete':'Ready';
    const phase=$('timer-phase');if(phase)phase.textContent=({work:'Work',short:'Short break',long:'Long break'})[timerState.phase];
    const start=$('timer-start');if(start){const resume=timerState.status==='paused';start.setAttribute('aria-label',resume?'Resume timer':'Start timer');start.setAttribute('title',resume?'Resume timer':'Start timer');start.disabled=!['idle','paused'].includes(timerState.status);}
    const pause=$('timer-pause');if(pause){pause.disabled=timerState.status!=='running';pause.setAttribute('aria-label','Pause timer');}
    const next=$('timer-next');if(next){next.disabled=!['finished','idle'].includes(timerState.status);next.setAttribute('aria-label','Start next phase');}
    const count=$('timer-count');if(count)count.textContent=String(timerState.completedWork);
    const sessionCount=$('timer-session-count');if(sessionCount)sessionCount.setAttribute('aria-label',`Completed work sessions: ${timerState.completedWork}`);
    const fullDuration=({work:timerConfig.workMinutes,short:timerConfig.shortBreakMinutes,long:timerConfig.longBreakMinutes}[timerState.phase]||1)*60000;
    const remainingFraction=Math.max(0,Math.min(1,ms/fullDuration));
    const progress=$('timer-progress');if(progress)progress.setAttribute('stroke-dashoffset',String(TIMER_RING_CIRCUMFERENCE*(1-remainingFraction)));
    const task=$('timer-task');if(task)task.textContent=timerState.taskId?'Work session linked to selected task':timerState.phase==='work'?'No task linked yet':'Breaks are not linked to tasks';
  }
  function timerMarkup(){return `<section class="pomodoro" aria-labelledby="timer-heading">
    <div class="timer-card-header"><h3 id="timer-heading">Pomodoro timer</h3><div class="timer-header-actions">
      <span class="timer-session-count" id="timer-session-count" title="Completed work sessions" aria-label="Completed work sessions: ${timerState.completedWork}"><svg class="flame-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12.2 2.5c.8 3.1-.4 4.6-2.2 6.4-1.2 1.2-2.1 2.3-2.1 4.3a4.1 4.1 0 0 0 8.2 0c0-1.5-.6-2.8-1.8-4.2.1 2.2-.8 3.2-1.5 3.8.2-3.1-1.5-5.5-.6-10.3Zm-.3 19a6.6 6.6 0 0 1-6.6-6.6c0-3.2 1.7-5.1 3.4-6.9C10.5 6.2 11.9 4.7 11.3 2c4.2 3.4 7.2 7.4 7.2 11.2a6.6 6.6 0 0 1-6.6 8.3Z" fill="currentColor"/></svg><span id="timer-count">${timerState.completedWork}</span></span>
      <button class="timer-settings-trigger" type="button" data-action="timer-settings-open" aria-haspopup="dialog" aria-controls="timer-settings-dialog"><span class="settings-emoji" aria-hidden="true">⚙️</span><span>Settings</span></button>
    </div></div>
    <div class="timer-dial"><svg class="timer-ring" viewBox="0 0 220 220" aria-hidden="true" focusable="false"><circle class="timer-ring-track" cx="110" cy="110" r="92"/><circle class="timer-ring-progress" id="timer-progress" cx="110" cy="110" r="92" stroke-dasharray="${TIMER_RING_CIRCUMFERENCE}" stroke-dashoffset="0" transform="rotate(-90 110 110)"/></svg><div class="timer-dial-center"><p class="timer-phase" id="timer-phase"></p><p class="timer-remaining" id="timer-remaining" role="timer" aria-live="off">25:00</p><p id="timer-state" role="status" aria-live="polite">Ready</p></div></div>
    <div class="timer-controls"><button id="timer-start" type="button" data-action="timer-start" aria-label="Start timer" title="Start timer"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 4.8v14.4L19 12 7 4.8Z" fill="currentColor"/></svg></button><button id="timer-pause" type="button" data-action="timer-pause" aria-label="Pause timer" title="Pause timer" disabled><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M7 5h4v14H7zm6 0h4v14h-4z" fill="currentColor"/></svg></button><button type="button" data-action="timer-reset" aria-label="Reset timer" title="Reset timer"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 11a8 8 0 1 1 2.3 5.7M4 5v6h6" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></button><button id="timer-next" type="button" data-action="timer-next" aria-label="Start next phase" title="Start next phase" disabled><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M5 5v14l10-7L5 5Zm11 0v14h3V5h-3Z" fill="currentColor"/></svg></button></div>
    <p id="timer-task" class="timer-task-note">${timerState.taskId?'Work session linked to selected task':timerState.phase==='work'?'No task linked yet':'Breaks are not linked to tasks'}</p>
  </section>`;}
  const loadErrorMarkup='<p class="error" role="alert">Could not load today’s tasks. Check your connection and try again.</p><button type="button" data-action="retry">Retry</button>';
  const PARIS_TIME_ZONE='Europe/Paris';
  const parisDate=instant=>{const parts=new Intl.DateTimeFormat('en-CA',{timeZone:PARIS_TIME_ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(instant);return `${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}-${parts.find(p=>p.type==='day').value}`;};
  const localDate=()=>parisDate(new Date());
  const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const titleKey=value=>String(value??'').normalize('NFKC').trim().replace(/\s+/g,' ').toLowerCase();
  function dateTime(){const d=new Date();$('clock').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:PARIS_TIME_ZONE,hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d);$('clock-date').textContent=new Intl.DateTimeFormat('en-GB',{timeZone:PARIS_TIME_ZONE,weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(d);}
  function saveFocus(){try{focusId?localStorage.setItem(KEY,focusId):localStorage.removeItem(KEY);}catch(_){}}
  function reconcileFocus(){if(!hasLoaded)return;const open=tasks.filter(t=>!t.completed);if(!open.some(t=>t.id===focusId)){focusId=open[0]?.id||null;saveFocus();}}
  function syncBusy(){app.setAttribute('aria-busy',String(busy));app.querySelectorAll('button,input,select,textarea').forEach(el=>{if(busy){el._busyWasDisabled=el.disabled;el.disabled=true;}else{el.disabled=el._busyWasDisabled||false;delete el._busyWasDisabled;}});}
  function taskLine(t,i,list,isFocus=false){if(editingId===t.id&&!isFocus)return `<form id="edit-form" class="inline-edit" data-id="${esc(t.id)}"><label>Title<input name="title" required maxlength="300" value="${esc(t.title)}"></label><label>Group<input name="group" maxlength="100" value="${esc(t.group||'')}"></label><label>Estimate<select name="estimate"><option value="" ${!t.estimate?'selected':''}>None</option><option value="S" data-size="S" ${t.estimate==='S'?'selected':''}>S</option><option value="M" data-size="M" ${t.estimate==='M'?'selected':''}>M</option><option value="L" data-size="L" ${t.estimate==='L'?'selected':''}>L</option></select></label><button type="submit">Save</button><button type="button" data-action="cancel-edit">Cancel</button></form>`;return `<div class="task-row${t.completed?' done':''}${isFocus?' current-focus':''}" data-id="${esc(t.id)}"><label class="check"><input type="checkbox" data-action="complete" ${t.completed?'checked':''} aria-label="${t.completed?'Reopen':'Complete'} ${esc(t.title)}"><span aria-hidden="true"></span></label><div class="task-main"><strong>${esc(t.title)}</strong><small>${esc(t.group||'Ungrouped')}</small></div><span class="effort" data-size="${esc(t.estimate||'')}">${esc(t.estimate||'—')}</span>${isFocus?'<span class="focus-mark">CURRENT FOCUS</span>':`<button class="icon-button" data-action="edit" aria-label="Edit ${esc(t.title)}">Edit</button><button class="drag-handle" type="button" draggable="true" aria-label="Reorder task: ${esc(t.title)} with Alt+ArrowUp/Alt+ArrowDown" title="Drag to reorder"><svg viewBox="0 0 20 20" aria-hidden="true" focusable="false"><rect x="2.5" y="2.5" width="15" height="15" rx="3" fill="none" stroke="currentColor"/><circle cx="7" cy="7" r="1" fill="currentColor"/><circle cx="13" cy="7" r="1" fill="currentColor"/><circle cx="7" cy="10" r="1" fill="currentColor"/><circle cx="13" cy="10" r="1" fill="currentColor"/><circle cx="7" cy="13" r="1" fill="currentColor"/><circle cx="13" cy="13" r="1" fill="currentColor"/></svg></button><button class="icon-button danger" data-action="delete" aria-label="Delete ${esc(t.title)}">Delete</button>`}</div>`;}
  function captureCreateDraft(){
    if(createDraftResetPending){createDraft={title:'',group:'',estimate:''};createDraftFocus={name:'title',selectionStart:0,selectionEnd:0};createDraftResetPending=false;return;}
    const form=$('create-form');if(!form)return;
    createDraft={title:form.elements.title.value,group:form.elements.group.value,estimate:form.elements.estimate.value};
    const active=document.activeElement;
    createDraftFocus=form.contains(active)&&active.name?{name:active.name,selectionStart:active.selectionStart,selectionEnd:active.selectionEnd}:null;
  }
  function restoreCreateDraft(){
    const form=$('create-form');if(!form){createDraftFocus=null;return;}
    Object.entries(createDraft).forEach(([name,value])=>{if(form.elements[name])form.elements[name].value=value;});
    if(!createDraftFocus)return;
    const field=form.elements[createDraftFocus.name];if(!field)return;
    field.focus();
    if(Number.isInteger(createDraftFocus.selectionStart)&&Number.isInteger(createDraftFocus.selectionEnd))field.setSelectionRange(createDraftFocus.selectionStart,createDraftFocus.selectionEnd);
  }
  function render(){
    captureCreateDraft();
    reconcileFocus();
    document.querySelectorAll('.view-nav [data-view]').forEach(b=>{b.setAttribute('aria-current',String(b.dataset.view===view?'page':'false'));b.setAttribute('aria-pressed',String(b.dataset.view===view));});
    if(view==='focus'){
      const chosen=tasks.find(t=>t.id===focusId&&!t.completed);
      const content=chosen?`<p class="focus-context">${esc(chosen.group||'Ungrouped')}</p>${taskLine(chosen,tasks.indexOf(chosen),tasks,true)}<h3>Other open tasks</h3><div class="focus-choices">${tasks.filter(t=>!t.completed&&t.id!==chosen.id).map(t=>`<button class="focus-choice" data-action="focus" data-id="${esc(t.id)}"><span>${esc(t.title)}</span><small>${esc(t.group||'Ungrouped')}</small></button>`).join('')}</div>`:loadError?loadErrorMarkup:'<p class="empty">No open tasks. Your list is clear.</p>';
      app.innerHTML=`<section class="focus-view"><p class="eyebrow">One thing at a time</p><h2>Focus</h2>${content}${timerMarkup()}${chosen&&loadError?loadErrorMarkup:''}</section>`;
    } else {
      const groups=new Map();tasks.forEach((t,i)=>{const g=t.group||'Ungrouped';if(!groups.has(g))groups.set(g,[]);groups.get(g).push({t,i});});
      const list=tasks.length?[...groups].map(([g,items])=>`<section class="section"><div class="section-head"><h2>${esc(g)}</h2></div>${items.map(({t,i})=>taskLine(t,i,tasks)).join('')}</section>`).join(''):loadError?loadErrorMarkup:'<p class="empty">Nothing planned for today. Add a task when you are ready.</p>';
      app.innerHTML=`<div class="summary"><span>Today's progress</span><div class="progress-track"><div class="progress-fill" style="width:${tasks.length?tasks.filter(t=>t.completed).length/tasks.length*100:0}%"></div></div><span>${tasks.filter(t=>t.completed).length} / ${tasks.length}</span></div>${list}${tasks.length&&loadError?loadErrorMarkup:''}<form id="create-form" class="create-form"><h2>Add a task</h2><p id="create-error" class="create-error" role="alert" ${createError?'':'hidden'}>${esc(createError)}</p><label>Task title<input name="title" required maxlength="300" autocomplete="off"></label><label>Group <input name="group" maxlength="100" placeholder="Optional"></label><label>Estimate <select name="estimate"><option value="">None</option><option value="S" data-size="S">S</option><option value="M" data-size="M">M</option><option value="L" data-size="L">L</option></select></label><input type="hidden" name="planned_date" value="${localDate()}"><button type="submit">Add task</button></form>`;
    }
    restoreCreateDraft();
    syncBusy();
    updateTimerDisplay();
  }
  async function request(url,options={}){const r=await fetch(url,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});if(!r.ok){const problem=await r.json().catch(()=>({}));const error=new Error(problem.error||`Request failed (${r.status})`);error.status=r.status;throw error;}return r.json().catch(()=>({}));}
  async function refresh(){const generation=++refreshGeneration;try{const data=await request(`${API}?date=${localDate()}`,{cache:'no-store'});if(generation!==refreshGeneration)return;tasks=Array.isArray(data.tasks)?data.tasks:[];hasLoaded=true;loadError=false;status.textContent='Shared tasks · Synced';render();}catch(_){if(generation!==refreshGeneration)return;loadError=true;status.textContent='Shared tasks · Offline — changes may not be shared';render();}}
  async function mutate(op){if(busy)return;busy=true;status.textContent='Saving…';syncBusy();try{await op();await refresh();}catch(error){await refresh();status.textContent=error?.status?'Shared tasks · Not saved':'Shared tasks · Offline — changes may not be shared';}finally{busy=false;syncBusy();}}
  function reorderTask(taskId,targetId){if(busy||taskId===targetId)return;const from=tasks.findIndex(task=>task.id===taskId),to=tasks.findIndex(task=>task.id===targetId);if(from<0||to<0)return;const reordered=[...tasks], [moved]=reordered.splice(from,1);reordered.splice(to,0,moved);tasks=reordered;render();mutate(()=>request(`${API}/reorder?date=${localDate()}`,{method:'PUT',body:JSON.stringify({task_ids:reordered.map(task=>task.id)})}));}
  document.querySelectorAll('.view-nav [data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;render();}));
  $('theme-toggle').addEventListener('click',()=>{const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;$('theme-toggle').setAttribute('aria-pressed',String(next==='dark'));$('theme-toggle').setAttribute('aria-label',`Switch to ${next==='dark'?'light':'dark'} theme`);try{localStorage.setItem(THEME_KEY,next);}catch(_){}});
  $('timer-settings').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target),checked=Timer.validateConfig(Object.fromEntries(Object.keys(Timer.DEFAULT_CONFIG).map(k=>[k,f.get(k)])));if(checked.valid){timerConfig=checked.config;saveTimerConfig();updateTimerDisplay();$('timer-settings-dialog').close();}else e.target.reportValidity();});
  $('timer-settings-dialog').addEventListener('click',e=>{const dialog=$('timer-settings-dialog');if(e.target===dialog||e.target.closest('[data-action="timer-settings-close"]'))dialog.close();});
  app.addEventListener('input',e=>{if(createError&&e.target.form?.id==='create-form'){createError='';const message=$('create-error');if(message){message.textContent='';message.hidden=true;}}});
  app.addEventListener('submit',e=>{if(busy){e.preventDefault();return;}if(e.target.id==='edit-form'){e.preventDefault();const f=new FormData(e.target),id=e.target.dataset.id;editingId=null;mutate(()=>request(`${API}/${encodeURIComponent(id)}`,{method:'PATCH',body:JSON.stringify({title:f.get('title'),group:f.get('group')||null,estimate:f.get('estimate')||null})}));return;}if(e.target.id!=='create-form')return;e.preventDefault();const f=new FormData(e.target),title=String(f.get('title')??'').trim(),plannedDate=f.get('planned_date');createError='';if(!title){createError='Task title is required.';render();return;}if(title.length>300){createError='Task title must be 300 characters or fewer.';render();return;}if(tasks.some(task=>task.planned_date===plannedDate&&titleKey(task.title)===titleKey(title))){createError='A task with this title already exists for this date.';render();return;}mutate(async()=>{try{await request(API,{method:'POST',body:JSON.stringify({title,planned_date:plannedDate,group:f.get('group')?.trim()||null,estimate:f.get('estimate')||null})});createDraftResetPending=true;createError='';}catch(error){createError=error.message;throw error;}});});
  app.addEventListener('dragstart',e=>{const handle=e.target.closest('.drag-handle');if(!handle)return;const row=handle.closest('.task-row[data-id]');if(!row)return;draggedTaskId=row.dataset.id;if(e.dataTransfer){e.dataTransfer.setData('text/plain',draggedTaskId);e.dataTransfer.effectAllowed='move';}});
  app.addEventListener('dragover',e=>{const row=e.target.closest('.task-row[data-id]');if(!draggedTaskId||!row||row.dataset.id===draggedTaskId)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';});
  app.addEventListener('drop',e=>{const row=e.target.closest('.task-row[data-id]');if(!row)return;const taskId=draggedTaskId||e.dataTransfer?.getData('text/plain');if(!taskId)return;e.preventDefault();draggedTaskId=null;reorderTask(taskId,row.dataset.id);});
  app.addEventListener('dragend',()=>{draggedTaskId=null;});
  app.addEventListener('keydown',e=>{const handle=e.target.closest('.drag-handle');if(!handle||!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const taskId=handle.closest('.task-row[data-id]')?.dataset.id,index=tasks.findIndex(task=>task.id===taskId),target=tasks[index+(e.key==='ArrowUp'?-1:1)];if(target)reorderTask(taskId,target.id);});
  app.addEventListener('change',e=>{if(e.target.dataset.action==='complete'){const t=tasks.find(x=>x.id===e.target.closest('[data-id]').dataset.id);if(busy){e.target.checked=!!t?.completed;return;}if(t)mutate(async()=>{try{await request(`${API}/${encodeURIComponent(t.id)}`,{method:'PATCH',body:JSON.stringify({completed:e.target.checked})});}catch(error){e.target.checked=!!t.completed;throw error;}});}});
  app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action.startsWith('timer-')){if(action==='timer-start')commitTimer(Timer.start(timerState,{now:Date.now(),config:timerConfig,selectedTaskId:focusId}));else if(action==='timer-pause')commitTimer(Timer.pause(timerState,Date.now()));else if(action==='timer-reset')commitTimer(Timer.reset(timerState));else if(action==='timer-next'){commitTimer(Timer.nextPhase(Timer.recover(timerState,Date.now()),timerConfig));}else if(action==='timer-settings-open'){Object.entries({workMinutes:'timer-work',shortBreakMinutes:'timer-short',longBreakMinutes:'timer-long',longBreakInterval:'timer-interval'}).forEach(([key,id])=>{$(id).value=timerConfig[key];});$('timer-settings-dialog').showModal();}return;}if(busy)return;const id=b.closest('[data-id]')?.dataset.id;if(action==='retry'){refresh();return;}if(action==='focus'){focusId=id;saveFocus();render();return;}const t=tasks.find(x=>x.id===id);if(!t)return;if(action==='delete'){mutate(()=>request(`${API}/${encodeURIComponent(id)}`,{method:'DELETE'}));return;}if(action==='edit'){editingId=id;render();return;}if(action==='cancel-edit'){editingId=null;render();return;}});
  let theme=null;try{theme=localStorage.getItem(THEME_KEY);}catch(_){}const initial=theme||(window.matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');document.documentElement.dataset.theme=initial;$('theme-toggle').setAttribute('aria-pressed',String(initial==='dark'));$('theme-toggle').setAttribute('aria-label',`Switch to ${initial==='dark'?'light':'dark'} theme`);try{focusId=localStorage.getItem(KEY);}catch(_){}dateTime();window.setInterval(dateTime,1000);window.setInterval(updateTimerDisplay,1000);refresh();window.setInterval(refresh,5000);
})();